#!/usr/bin/env python3
"""打印前 10 个斐波那契数（从 0, 1 开始）。"""


def fibonacci(n):
    """返回前 n 个斐波那契数组成的列表。"""
    seq = []
    a, b = 0, 1
    for _ in range(n):
        seq.append(a)
        a, b = b, a + b
    return seq


def main():
    numbers = fibonacci(10)
    print("前 10 个斐波那契数：")
    for i, num in enumerate(numbers, start=1):
        print(f"{i:2d}: {num}")


if __name__ == "__main__":
    main()

